import type { LayerDescriptor } from '../../types/api'

function baseDisplay(overrides: Partial<LayerDescriptor['display']> = {}): LayerDescriptor['display'] {
  return {
    display_name: 'Layer',
    palette: { kind: 'single_color', color: '#333333', colormap_name: null, domain: null, midpoint: null, stops: [] },
    legend: { title: 'Layer', unit: null, kind: 'single_color', stops: [], note: null },
    units: null,
    opacity: 1,
    z_index: 10,
    tooltip_fields: [],
    default_visible: true,
    scientific_limitations: [],
    ...overrides,
  }
}

